//! Associated template Documents share checked tree and live metadata semantics.
use super::*;
fn fixture()->(Document,Forms,Page){let mut doc=crate::html::parse("<!doctype html><html><body><span id=mount></span><input id=field value=seed></body></html>");doc.scripting_enabled=true;let mut forms=Forms::new(&doc);let mut page=Page::new();page.set_location(&crate::navigation::address("https://attribute-factories.test/source",&crate::navigation::Location::home()).unwrap());assert_eq!(page.start(&mut doc,&mut forms,&[]).errors,0);(doc,forms,page)}
fn run(doc:&mut Document,forms:&mut Forms,page:&mut Page,source:&str){assert_eq!(page.console_eval(doc,forms,source).errors,0,"{source}\n{}",page.report());}


#[test]
fn template_document_children_real_roots_doctype_live_metadata_and_separate_contents(){
 let(mut doc,mut forms,mut page)=fixture();run(&mut doc,&mut forms,&mut page,r#"
var ns='http://www.w3.org/1999/xhtml',xml=document.implementation.createDocument(null,''),html=document.implementation.createHTMLDocument('source');for(var source of [html,xml]){var host=source.createElementNS(ns,'template'),content=host.content,owner=content.ownerDocument,view=owner.childNodes,elements=owner.children,root=owner.createElementNS(ns,'html'),head=owner.createElementNS(ns,'head'),body=owner.createElementNS(ns,'body'),title=owner.createElementNS(ns,'title'),base=owner.createElementNS(ns,'base'),dtype=owner.implementation.createDocumentType('html','',''),comment=owner.createComment('before');title.appendChild(owner.createTextNode('  actual \ud800 title  '));head.appendChild(title);base.setAttribute('href','https://template-document-base.test/root/');head.appendChild(base);root.appendChild(head);root.appendChild(body);owner.appendChild(comment);owner.appendChild(dtype);owner.appendChild(root);var leaf=owner.createElementNS(ns,'span');leaf.textContent='separate';content.appendChild(leaf);
var checks=[owner.documentElement!==root,owner.doctype!==dtype,root.parentNode!==owner,dtype.ownerDocument!==owner,view.length!==3,view[2]!==root,elements.length!==1,elements[0]!==root,owner.head!==head,owner.body!==body,owner.title!=='actual \ud800 title',owner.contentType!=='application/xml',owner.URL!=='about:blank',owner.baseURI!=='https://template-document-base.test/root/',leaf.baseURI!==owner.baseURI,owner.defaultView!==null,owner instanceof XMLDocument,owner.createAttribute('MiXeD').name!==(source===html?'mixed':'MiXeD'),content.ownerDocument!==owner,content.parentNode!==null,leaf.parentNode!==content,!root.isConnected,leaf.isConnected];for(var i=0;i<checks.length;i++){if(checks[i])throw 'associated metadata check '+i;}var nested=owner.createElementNS(ns,'template');if(nested.content.ownerDocument!==owner)throw 'algorithm-created marker survives document mutation';var copy=owner.cloneNode(true);if(copy===owner||copy.documentElement===root||copy.documentElement.ownerDocument!==copy||copy.doctype===dtype||copy.doctype.ownerDocument!==copy||copy.title!==owner.title||copy instanceof XMLDocument||copy.baseURI!==owner.baseURI||copy.createElementNS(ns,'template').content.ownerDocument===copy)throw 'ordinary clone copies actual template document children without marker';owner.removeChild(root);if(owner.documentElement!==null||owner.head!==null||owner.body!==null||owner.title!==''||elements.length||owner.doctype!==dtype||root.parentNode!==null||view.length!==2||content.firstChild!==leaf||owner.baseURI!=='about:blank'||leaf.baseURI!=='about:blank')throw 'live removal leaves separate contents intact';owner.removeChild(dtype);if(owner.doctype!==null||view.length!==1)throw 'live doctype removal';}
"#);
}
#[test]
fn template_document_children_shared_hierarchy_fragment_replacement_and_observation(){
 let(mut doc,mut forms,mut page)=fixture();run(&mut doc,&mut forms,&mut page,r#"
var ns='http://www.w3.org/1999/xhtml',owner=document.createElement('template').content.ownerDocument,root=owner.createElement('html'),watch=new MutationObserver(function(){});watch.observe(owner,{childList:true});owner.appendChild(root);if(watch.takeRecords().length!==1)throw 'document mutation observation';for(var bad of [owner.createTextNode('x'),owner.createElement('second'),root]){var caught=false;try{owner.appendChild(bad);}catch(e){caught=e instanceof DOMException&&e.name==='HierarchyRequestError';}if(!caught||owner.documentElement!==root||owner.childNodes.length!==1||watch.takeRecords().length)throw 'shared document hierarchy and incoming-node exclusion';}var fragment=owner.createDocumentFragment(),next=owner.createElement('replacement'),comment=owner.createComment('next');fragment.appendChild(comment);fragment.appendChild(next);var donorWatch=new MutationObserver(function(){});donorWatch.observe(fragment,{childList:true});if(owner.replaceChild(fragment,root)!==root||root.parentNode!==null||fragment.childNodes.length||owner.firstChild!==comment||owner.documentElement!==next||next.parentNode!==owner)throw 'actual fragment replacement topology';var records=watch.takeRecords(),donor=donorWatch.takeRecords();if(records.length!==1||records[0].target!==owner||records[0].addedNodes.length!==2||records[0].removedNodes[0]!==root||donor.length!==1||donor[0].removedNodes.length!==2)throw 'source and destination mutation records';var dtype=owner.implementation.createDocumentType('html','',''),caught=false;try{owner.appendChild(dtype);}catch(e){caught=e.name==='HierarchyRequestError';}if(!caught||dtype.parentNode!==null)throw 'doctype order';owner.insertBefore(dtype,next);if(owner.doctype!==dtype||owner.childNodes[1]!==dtype)throw 'valid doctype insertion';
"#);
}
#[test]
fn template_document_children_namespace_default_uses_real_document_element(){
 let(mut doc,mut forms,mut page)=fixture();run(&mut doc,&mut forms,&mut page,"var xml=document.implementation.createDocument(null,''),owner=xml.createElementNS('http://www.w3.org/1999/xhtml','template').content.ownerDocument,root=owner.createElementNS('urn:original','Root');owner.appendChild(root);if(!owner.isDefaultNamespace('urn:original')||owner.isDefaultNamespace(null)||owner.documentElement!==root)throw 'document namespace context';owner.removeChild(root);if(owner.isDefaultNamespace('urn:original')||!owner.isDefaultNamespace(null))throw 'removed root namespace context';");
}

#[test]
fn template_document_children_saved_child_mutator_origin_precedes_publication(){
 let(mut doc,mut forms,mut page)=fixture();run(&mut doc,&mut forms,&mut page,"var owner=document.createElement('template').content.ownerDocument,frame=document.createElement('iframe');frame.hidden=true;document.body.appendChild(frame);var saved=frame.contentWindow.Node.prototype.appendChild,root=owner.createElement('html');if(saved.call(owner,root)!==root||owner.documentElement!==root)throw 'genuine captured owner mutator';var comment=owner.createComment('held');");page.set_location(&crate::navigation::address("https://other-template-document.test/",&crate::navigation::Location::home()).unwrap());let before=(doc.nodes.len(),page.state.retained,page.state.dom_commits);assert_eq!(page.console_eval(&mut doc,&mut forms,"saved.call(owner,comment);").errors,1);assert!(page.report().contains("same-origin")||page.report().contains("Security"),"{}",page.report());assert_eq!((doc.nodes.len(),page.state.retained,page.state.dom_commits),before);run(&mut doc,&mut forms,&mut page,"if(owner.documentElement!==root||owner.childNodes.length!==1||comment.parentNode!==null)throw 'origin refusal leaves tree and metadata intact';");
}
